+12|  function isMissing(x) {
+13|    return x === null || x === undefined || x === '' || (typeof x === 'number' && !Number.isFinite(x));
+14|  }
+15|
+16|  function formatMarketCap(n) {
+17|    if (!Number.isFinite(n)) return '—';
+18|
+19|    const abs = Math.abs(n);
+20|    const fmt = (value, suffix, digits) => {
+21|      const s = value.toFixed(digits);
+22|      const trimmed = s.replace(/\.0+$/, '').replace(/(\.\d*[1-9])0+$/, '$1');
+23|      return `${trimmed}${suffix}`;
+24|    };
+25|
+26|    if (abs >= 1e12) return fmt(n / 1e12, 'T', abs >= 1e13 ? 1 : 2);
+27|    if (abs >= 1e9) return fmt(n / 1e9, 'B', abs >= 1e10 ? 1 : 2);
+28|    if (abs >= 1e6) return fmt(n / 1e6, 'M', abs >= 1e7 ? 1 : 2);
+29|    if (abs >= 1e3) return fmt(n / 1e3, 'K', abs >= 1e4 ? 1 : 2);
+30|    return String(Math.round(n));
+31|  }
+32|
+33|  function parseRow(d) {
+34|    const marketCap = d.marketCap === '' ? NaN : +d.marketCap;
+35|    const sector = d.sector;
+36|
+37|    const etf = sector === 'ETF' || !Number.isFinite(marketCap);
+38|
+39|    return {
+40|      ticker: d.ticker,
+41|      sector,
+42|      fullName: d['full name'],
+43|      marketCap: Number.isFinite(marketCap) ? marketCap : null,
+44|      isETF: etf,
+45|    };
+46|  }
