+48|  async function loadStockDescriptions() {
+49|    try {
+50|      return await d3.csv(DATA_URL, parseRow);
+51|    } catch (err) {
+52|      const embedded = document.getElementById('embedded-stock-descriptions');
+53|      if (!embedded) throw err;
+54|      const text = embedded.textContent.trim();
+55|      return d3.csvParse(text, parseRow);
+56|    }
+57|  }
